package org.apache.commons.cli;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Assertions;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Map;

class OptionsHasLongOptionTest {

    private Options options;
    @SuppressWarnings("rawtypes")
    private Map longOptsMap;

    @BeforeEach
    void setUp() throws Exception {
        options = new Options();
        Field longOptsField = Options.class.getDeclaredField("longOpts");
        longOptsField.setAccessible(true);
        Object mapObj = longOptsField.get(options);
        // generics erased at runtime; cast to raw Map to avoid referring to Option type
        longOptsMap = (Map) mapObj;
        longOptsMap.clear();
    }

    // helper to add an entry to the private longOpts map
    private void addLongOpt(String key) {
        longOptsMap.put(key, null);
    }

    // helper to invoke Util.stripLeadingHyphens via reflection
    private String invokeStripLeadingHyphens(String input) throws Exception {
        Class<?> utilClass = Class.forName("org.apache.commons.cli.Util");
        Method m = utilClass.getDeclaredMethod("stripLeadingHyphens", String.class);
        m.setAccessible(true);
        return (String) m.invoke(null, input);
    }

    @Test
    void testStripLeadingHyphens_reflectionVariety() throws Exception {
        // verify behavior for various inputs via reflection
        Assertions.assertEquals("opt", invokeStripLeadingHyphens("--opt"));
        Assertions.assertEquals("opt", invokeStripLeadingHyphens("-opt"));
        Assertions.assertEquals("opt", invokeStripLeadingHyphens("opt"));
        // empty and null should be returned as-is by the implementation
        Assertions.assertEquals("", invokeStripLeadingHyphens(""));
        Assertions.assertNull(invokeStripLeadingHyphens(null));
    }

    @Test
    void testHasLongOption_exactNamePresent() {
        addLongOpt("verbose");
        Assertions.assertTrue(options.hasLongOption("verbose"));
    }

    @Test
    void testHasLongOption_withDoubleHyphensMatchesStoredKey() {
        addLongOpt("verbose");
        Assertions.assertTrue(options.hasLongOption("--verbose"));
    }

    @Test
    void testHasLongOption_withSingleHyphenMatchesStoredKey() {
        addLongOpt("v");
        // stripLeadingHyphens will convert "-v" to "v", so it should return true
        Assertions.assertTrue(options.hasLongOption("-v"));
    }

    @Test
    void testHasLongOption_missingReturnsFalse() {
        addLongOpt("existing");
        Assertions.assertFalse(options.hasLongOption("nonexistent"));
    }

    @Test
    void testHasLongOption_nullInput_whenNullKeyPresent() {
        // Put a null key into the map and confirm that hasLongOption(null) returns true
        addLongOpt(null);
        Assertions.assertTrue(options.hasLongOption(null));
    }

    @Test
    void testHasLongOption_nullInput_whenNoNullKey() {
        // Ensure no null key present
        longOptsMap.remove(null);
        Assertions.assertFalse(options.hasLongOption(null));
    }

    @Test
    void testHasLongOption_emptyStringBehavior() {
        // empty string: stripLeadingHyphens likely returns empty string; ensure behavior consistent
        // Add empty-string key and assert true, and when absent assert false
        Assertions.assertFalse(options.hasLongOption(""));
        addLongOpt("");
        Assertions.assertTrue(options.hasLongOption(""));
    }
}

